cypress_script:
describe('Asynchronously Loaded Content', () => {
  it('should load content after clicking Start button', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('#start button').click();
    cy.get('#finish').should('be.visible');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('#finish').contains('Hello World!');
  });

  it('should not show finish content before clicking Start button', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('#finish').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Asynchronously Loaded Content', () => {
  test('should load content after clicking Start button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('#start button');
    await expect(page.locator('#finish')).toBeVisible();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page.locator('#finish')).toHaveText('Hello World!');
  });

  test('should not show finish content before clicking Start button', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page.locator('#finish')).toBeHidden();
  });
});
